import{_ as e,o,c as s,a5 as t}from"./chunks/framework.B5tqjWbr.js";const h=JSON.parse('{"title":"示例 2：自定义速度/负载曲线","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"simulation","chapterTitle":"仿真与调试","chapterOrder":10,"category":"仿真与调试","source":"motor","visibility":"public","title":"示例 2：自定义速度/负载曲线","tags":["motor-control"],"status":"learning","summary":"学会修改 `pmsm_comm.c` 的 `_user_commands()` 函数来设计自己的仿真场景。","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/simulation/code-examples/02-custom-speed-profile/README.md","filePath":"content/motor/simulation/code-examples/02-custom-speed-profile/README.md","lastUpdated":null}'),n={name:"content/motor/simulation/code-examples/02-custom-speed-profile/README.md"};function i(l,a,r,c,d,p){return o(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="示例-2-自定义速度-负载曲线" tabindex="-1">示例 2：自定义速度/负载曲线 <a class="header-anchor" href="#示例-2-自定义速度-负载曲线" aria-label="Permalink to &quot;示例 2：自定义速度/负载曲线&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>学会修改 <code>pmsm_comm.c</code> 的 <code>_user_commands()</code> 函数来设计自己的仿真场景。</p><h2 id="要修改的文件" tabindex="-1">要修改的文件 <a class="header-anchor" href="#要修改的文件" aria-label="Permalink to &quot;要修改的文件&quot;">​</a></h2><p><code>E:\\new_things\\emachinery\\emachinery\\frameworkCodes\\c\\pmsm_comm.c</code></p><h2 id="修改方案" tabindex="-1">修改方案 <a class="header-anchor" href="#修改方案" aria-label="Permalink to &quot;修改方案&quot;">​</a></h2><p>在 <code>_user_commands()</code> 函数中找到 <code>#if PC_SIMULATION == TRUE</code> 块（约第 734 行），修改速度指令和负载转矩。以下是一个典型测试场景：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间轴：</span></span>
<span class="line"><span>  0.00s - 速度指令 0 rpm，电机静止准备</span></span>
<span class="line"><span>  0.01s - 速度阶跃到 +400 rpm，正向加速</span></span>
<span class="line"><span>  0.04s - 突加满载（额定电流 50% 对应转矩）</span></span>
<span class="line"><span>  0.07s - 撤除负载，恢复到空载</span></span>
<span class="line"><span>  0.10s - 速度反转到 -300 rpm</span></span></code></pre></div><h2 id="预期效果" tabindex="-1">预期效果 <a class="header-anchor" href="#预期效果" aria-label="Permalink to &quot;预期效果&quot;">​</a></h2><ul><li>Speed 子图：0→400rpm 阶跃（略有超调后稳定）→ 突加负载掉速 → 恢复 → 反转</li><li>iQ 子图：加速时冲到限幅，稳速下降，加负载时回升</li><li>Torque 子图：Tem 跟随 TLoad，加减速时有惯量转矩叠加</li></ul><h2 id="修改要点" tabindex="-1">修改要点 <a class="header-anchor" href="#修改要点" aria-label="Permalink to &quot;修改要点&quot;">​</a></h2><ul><li><code>(*CTRL).i-&gt;cmd_varOmega = xxx * RPM_2_MECH_RAD_PER_SEC</code> — 速度指令</li><li><code>ACM.TLoad = xxx</code> — 负载转矩 [Nm]</li><li><code>(*CTRL).timebase</code> — 仿真时间（从 0 开始，单位秒）</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>必须在 <code>#if PC_SIMULATION == TRUE</code> 块中修改</li><li>不同 <code>WHO_IS_USER</code> 的用户有各自的指令块，确保在正确的位置修改</li></ul>`,14)])])}const u=e(n,[["render",i]]);export{h as __pageData,u as default};
